import { Router, Request, Response } from 'express';

export interface CreateBookmarkInput {
  url: string;
  title?: string;
  tags?: string[];
}

function isCreateBookmarkInput(value: unknown): value is CreateBookmarkInput {
  if (typeof value !== 'object' || value === null) {
    return false;
  }

  const record = value as Record<string, unknown>;

  if (typeof record['url'] !== 'string') {
    return false;
  }

  if ('title' in record && record['title'] !== undefined && typeof record['title'] !== 'string') {
    return false;
  }

  if ('tags' in record && record['tags'] !== undefined) {
    if (!Array.isArray(record['tags'])) {
      return false;
    }
    if (!record['tags'].every((tag: unknown): tag is string => typeof tag === 'string')) {
      return false;
    }
  }

  return true;
}

export const bookmarksRouter = Router();

bookmarksRouter.post('/', (req: Request, res: Response) => {
  const body: unknown = req.body;

  if (!isCreateBookmarkInput(body)) {
    res.status(400).json({ error: 'Invalid bookmark payload' });
    return;
  }

  res.status(201).json({
    url: body.url,
    title: body.title,
    tags: body.tags,
  });
});

export default bookmarksRouter;

import { Router, Request, Response } from 'express';
import { z } from 'zod';

export const createBookmarkSchema = z.object({
  url: z.string().url().max(2048),
  title: z.string().max(200).optional(),
  tags: z.array(z.string().max(50)).max(10).optional(),
});

export type CreateBookmarkInput = z.infer<typeof createBookmarkSchema>;

export const bookmarksRouter = Router();

bookmarksRouter.post('/', (req: Request, res: Response) => {
  const body: unknown = req.body;
  const result = createBookmarkSchema.safeParse(body);

  if (!result.success) {
    res.status(400).json({
      error: 'Validation failed',
      details: result.error.issues,
    });
    return;
  }

  res.status(201).json({
    url: result.data.url,
    title: result.data.title,
    tags: result.data.tags,
  });
});

export default bookmarksRouter;

import { randomUUID } from 'node:crypto';

export interface CreateBookmarkDTO {
  url: string;
  title?: string;
  tags?: string[];
}

export interface Bookmark {
  id: string;
  url: string;
  title?: string;
  tags?: string[];
  createdAt: string;
}

export class DuplicateBookmarkError extends Error {
  constructor(url: string) {
    super(`Bookmark with URL already exists: ${url}`);
    this.name = 'DuplicateBookmarkError';
  }
}

export class BookmarkService {
  private readonly bookmarks: Map<string, Bookmark> = new Map();

  create(input: CreateBookmarkDTO): Bookmark {
    for (const bookmark of this.bookmarks.values()) {
      if (bookmark.url === input.url) {
        throw new DuplicateBookmarkError(input.url);
      }
    }

    const bookmark: Bookmark = {
      id: randomUUID(),
      url: input.url,
      ...(input.title !== undefined ? { title: input.title } : {}),
      ...(input.tags !== undefined ? { tags: [...input.tags] } : {}),
      createdAt: new Date().toISOString(),
    };

    this.bookmarks.set(bookmark.id, bookmark);
    return bookmark;
  }

  getById(id: string): Bookmark | undefined {
    return this.bookmarks.get(id);
  }

  get(id: string): Bookmark | undefined {
    return this.getById(id);
  }

  getAll(): Bookmark[] {
    return Array.from(this.bookmarks.values()).sort(
      (a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime()
    );
  }

  delete(id: string): boolean {
    return this.bookmarks.delete(id);
  }

  clear(): void {
    this.bookmarks.clear();
  }
}

export const bookmarkService = new BookmarkService();

import { Router, Request, Response, NextFunction } from 'express';
import { z } from 'zod';
import { bookmarkService, DuplicateBookmarkError } from '../services/bookmark-service.js';

export const createBookmarkSchema = z.object({
  url: z.string().url().max(2048),
  title: z.string().max(200).optional(),
  tags: z.array(z.string().max(50)).max(10).optional(),
});

export type CreateBookmarkInput = z.infer<typeof createBookmarkSchema>;

export const bookmarksRouter = Router();

bookmarksRouter.post('/', (req: Request, res: Response, next: NextFunction) => {
  try {
    const body: unknown = req.body;
    const result = createBookmarkSchema.safeParse(body);

    if (!result.success) {
      res.status(400).json({
        error: 'Validation failed',
        details: result.error.issues,
      });
      return;
    }

    const bookmark = bookmarkService.create(result.data);
    res.status(201).json(bookmark);
  } catch (err: unknown) {
    if (err instanceof DuplicateBookmarkError) {
      res.status(409).json({ error: err.message });
      return;
    }
    next(err);
  }
});

export default bookmarksRouter;

