import { Request, Response, NextFunction } from 'express';
import { ZodError } from 'zod';
import { DuplicateBookmarkError } from '../services/bookmark-service.js';

function isInvalidJsonError(err: unknown): boolean {
  if (err instanceof SyntaxError) {
    const record = err as Record<string, unknown>;
    if (
      record['status'] === 400 ||
      record['statusCode'] === 400 ||
      record['type'] === 'entity.parse.failed'
    ) {
      return true;
    }
  }
  return false;
}

export function errorHandler(
  err: unknown,
  _req: Request,
  res: Response,
  _next: NextFunction
): void {
  if (isInvalidJsonError(err)) {
    res.status(400).json({ error: 'Invalid JSON payload' });
    return;
  }

  if (err instanceof ZodError) {
    res.status(422).json({
      error: 'Validation failed',
      details: err.errors,
    });
    return;
  }

  if (err instanceof DuplicateBookmarkError) {
    res.status(409).json({ error: err.message });
    return;
  }

  res.status(500).json({ error: 'Internal server error' });
}

import { Router, Request, Response, NextFunction } from 'express';
import { z } from 'zod';
import { bookmarkService } from '../services/bookmark-service.js';

export const createBookmarkSchema = z.object({
  url: z.string().url().max(2048),
  title: z.string().max(200).optional(),
  tags: z.array(z.string().max(50)).max(10).optional(),
});

export type CreateBookmarkInput = z.infer<typeof createBookmarkSchema>;

export const bookmarksRouter = Router();

bookmarksRouter.post('/', (req: Request, res: Response, next: NextFunction) => {
  try {
    const body: unknown = req.body;
    const validatedData = createBookmarkSchema.parse(body);
    const bookmark = bookmarkService.create(validatedData);
    res.status(201).json(bookmark);
