import { Request, Response, NextFunction } from 'express';
import { ZodError } from 'zod';
import { DuplicateBookmarkError } from '../services/bookmark-service.js';

function isInvalidJsonError(err: unknown): boolean {
  if (err instanceof SyntaxError && 'status' in err) {
    const candidate = err as { status: unknown; statusCode?: unknown; type?: unknown };
    return (
      candidate.status === 400 ||
      candidate.statusCode === 400 ||
      candidate.type === 'entity.parse.failed'
    );
  }
  return false;
}

export function errorHandler(
  err: unknown,
  _req: Request,
  res: Response,
  _next: NextFunction
): void {
  if (isInvalidJsonError(err)) {
    res.status(400).json({ error: 'Invalid JSON payload' });
    return;
  }

  if (err instanceof ZodError) {
    res.status(422).json({
      error: 'Validation failed',
      details: err.issues,
    });
    return;
  }

  if (err instanceof DuplicateBookmarkError) {
    res.status(409).json({ error: err.message });
    return;
  }

  res.status(500).json({ error: 'Internal server error' });
}

