import { describe, it, expect } from 'vitest';
import { createBookmarkSchema } from './bookmarks.js';

describe('createBookmarkSchema zod validation', () => {
  it('should accept valid inputs with url, title, and tags', () => {
    const input = {
      url: 'https://example.com',
      title: 'Example Domain',
      tags: ['web', 'reference'],
    };
    const result = createBookmarkSchema.safeParse(input);
    expect(result.success).toBe(true);
    if (result.success) {
      expect(result.data.url).toBe(input.url);
      expect(result.data.title).toBe(input.title);
      expect(result.data.tags).toEqual(input.tags);
    }
  });

  it('should accept valid inputs with only required url', () => {
    const input = {
      url: 'https://example.com',
    };
    const result = createBookmarkSchema.safeParse(input);
    expect(result.success).toBe(true);
    if (result.success) {
      expect(result.data.url).toBe(input.url);
      expect(result.data.title).toBeUndefined();
      expect(result.data.tags).toBeUndefined();
    }
  });

  it('should reject missing url', () => {
    const input: Record<string, unknown> = {
      title: 'Missing URL',
    };
    const result = createBookmarkSchema.safeParse(input);
    expect(result.success).toBe(false);
    if (!result.success) {
      const issue = result.error.issues.find((item) => item.path.includes('url'));
      expect(issue).toBeDefined();
    }
  });

  it('should reject an invalid url format', () => {
    const input = {
      url: 'not-a-valid-url',
    };
    const result = createBookmarkSchema.safeParse(input);
    expect(result.success).toBe(false);
  });

  it('should reject url that is too long (> 2048 characters)', () => {
    const longPath = 'a'.repeat(2050);
    const input = {
      url: `https://example.com/${longPath}`,
    };
    const result = createBookmarkSchema.safeParse(input);
    expect(result.success).toBe(false);
    if (!result.success) {
      const issue = result.error.issues.find((item) => item.path.includes('url'));
      expect(issue).toBeDefined();
    }
  });

  it('should reject too many tags (> 10)', () => {
    const input = {
      url: 'https://example.com',
      tags: Array.from({ length: 11 }, (_: unknown, i: number) => `tag-${i}`),
    };
    const result = createBookmarkSchema.safeParse(input);
    expect(result.success).toBe(false);
    if (!result.success) {
      const issue = result.error.issues.find((item) => item.path.includes('tags'));
      expect(issue).toBeDefined();
    }
  });

  it('should reject a tag that is too long (> 50 characters)', () => {
    const input = {
      url: 'https://example.com',
      tags: ['valid-tag', 'a'.repeat(51)],
    };
    const result = createBookmarkSchema.safeParse(input);
    expect(result.success).toBe(false);
    if (!result.success) {
      const issue = result.error.issues.find((item) => item.path.includes('tags'));
      expect(issue).toBeDefined();
    }
  });

  it('should reject a title that is too long (> 200 characters)', () => {
    const input = {
      url: 'https://example.com',
      title: 'a'.repeat(201),
    };
    const result = createBookmarkSchema.safeParse(input);
    expect(result.success).toBe(false);
    if (!result.success) {
      const issue = result.error.issues.find((item) => item.path.includes('title'));
      expect(issue).toBeDefined();
    }
  });
});

import { describe, it, expect, beforeEach } from 'vitest';
import { BookmarkService, DuplicateBookmarkError } from './bookmark-service.js';

describe('BookmarkService', () => {
  let service: BookmarkService;

  beforeEach(() => {
    service = new BookmarkService();
  });

  describe('create', () => {
    it('should create a bookmark with id and createdAt timestamp', () => {
      const input = {
        url: 'https://example.com/article',
        title: 'Great Article',
        tags: ['tech', 'news'],
      };

      const bookmark = service.create(input);

      expect(bookmark.id).toBeDefined();
      expect(typeof bookmark.id).toBe('string');
      expect(bookmark.url).toBe(input.url);
      expect(bookmark.title).toBe(input.title);
      expect(bookmark.tags).toEqual(input.tags);
      expect(bookmark.createdAt).toBeDefined();
      expect(new Date(bookmark.createdAt).toString()).not.toBe('Invalid Date');
    });

    it('should create a bookmark with only url', () => {
      const bookmark = service.create({ url: 'https://minimal.com' });

      expect(bookmark.id).toBeDefined();
      expect(bookmark.url).toBe('https://minimal.com');
      expect(bookmark.title).toBeUndefined();
      expect(bookmark.tags).toBeUndefined();
    });

    it('should generate unique ids for separate bookmarks', () => {
      const first = service.create({ url: 'https://first.com' });
      const second = service.create({ url: 'https://second.com' });

      expect(first.id).not.toBe(second.id);
    });
  });

  describe('duplicate detection', () => {
    it('should throw DuplicateBookmarkError when adding a bookmark with an existing URL', () => {
      const url = 'https://duplicate.com';
      service.create({ url, title: 'First' });

      expect(() => {
        service.create({ url, title: 'Second' });
      }).toThrowError(DuplicateBookmarkError);
    });

    it('should include the conflicting URL in the duplicate error', () => {
      const url = 'https://duplicate-message.com';
      service.create({ url });

      try {
        service.create({ url });
        expect.unreachable('Should have thrown DuplicateBookmarkError');
      } catch (err: unknown) {
        expect(err).toBeInstanceOf(DuplicateBookmarkError);
        if (err instanceof DuplicateBookmarkError) {
          expect(err.message).toContain(url);
        }
      }
    });

    it('should allow bookmarks with distinct URLs', () => {
      expect(() => {
        service.create({ url: 'https://site-a.com' });
        service.create({ url: 'https://site-b.com' });
      }).not.toThrow();
    });
  });

  describe('retrieval', () => {
    it('should retrieve a bookmark by id via getById', () => {
      const created = service.create({
        url: 'https://retrieve.com',
        title: 'Retrieve Me',
      });

      const found = service.getById(created.id);
      expect(found).toBeDefined();
      expect(found).toEqual(created);
    });

    it('should retrieve a bookmark by id via get alias', () => {
      const created = service.create({ url: 'https://alias.com' });

      const found = service.get(created.id);
      expect(found).toEqual(created);
    });

    it('should return undefined for non-existent id', () => {
      const notFound = service.getById('non-existent-uuid');
      expect(notFound).toBeUndefined();
    });

    it('should retrieve all bookmarks sorted by createdAt descending via getAll', () => {
      const b1 = service.create({ url: 'https://one.com' });
      const b2 = service.create({ url: 'https://two.com' });

      const all = service.getAll();
      expect(all).toHaveLength(2);
      expect(all.map((b) => b.id)).toEqual([b2.id, b1.id]);
    });
  });
});

