    it('should return 200 and the bookmark matching the given id', async () => {
      const createRes = await request(app)
        .post('/api/v1/bookmarks')
        .send({ url: 'https://single.com', title: 'Single' });

      const created: unknown = createRes.body;
      expect(isBookmarkResponse(created)).toBe(true);

      if (isBookmarkResponse(created)) {
        const res = await request(app).get(`/api/v1/bookmarks/${created.id}`);

        expect(res.status).toBe(200);
        const body: unknown = res.body;
        expect(isBookmarkResponse(body)).toBe(true);
        if (isBookmarkResponse(body)) {
          expect(body.id).toBe(created.id);
          expect(body.url).toBe(created.url);
          expect(body.title).toBe(created.title);
        }
      }
    });
  });

  describe('DELETE /api/v1/bookmarks/:id', () => {
    it('should delete the bookmark, returning 204, and verify subsequent 404', async () => {
      const createRes = await request(app)
        .post('/api/v1/bookmarks')
        .send({ url: 'https://delete-me.com' });

      const created: unknown = createRes.body;
      expect(isBookmarkResponse(created)).toBe(true);

      if (isBookmarkResponse(created)) {
        const deleteRes = await request(app).delete(`/api/v1/bookmarks/${created.id}`);
        expect(deleteRes.status).toBe(204);

        const getRes = await request(app).get(`/api/v1/bookmarks/${created.id}`);
        expect(getRes.status).toBe(404);
      }
    });
  });

  describe('Full CRUD lifecycle', () => {
    it('should handle full sequence: POST -> GET list -> GET single -> DELETE -> GET single 404', async () => {
      // 1. Create
      const postRes = await request(app)
        .post('/api/v1/bookmarks')
        .send({ url: 'https://full-lifecycle.com', title: 'Lifecycle' });
      expect(postRes.status).toBe(201);
      const postBody: unknown = postRes.body;
      expect(isBookmarkResponse(postBody)).toBe(true);
      if (!isBookmarkResponse(postBody)) return;

      const bookmarkId = postBody.id;

      // 2. List
      const listRes = await request(app).get('/api/v1/bookmarks');
      expect(listRes.status).toBe(200);
      const listBody: unknown = listRes.body;
      expect(isBookmarkArray(listBody)).toBe(true);
      if (isBookmarkArray(listBody)) {
        expect(listBody.some((b) => b.id === bookmarkId)).toBe(true);
      }

      // 3. Single
      const singleRes = await request(app).get(`/api/v1/bookmarks/${bookmarkId}`);
      expect(singleRes.status).toBe(200);
      const singleBody: unknown = singleRes.body;
      expect(isBookmarkResponse(singleBody)).toBe(true);

      // 4. Delete
      const delRes = await request(app).delete(`/api/v1/bookmarks/${bookmarkId}`);
      expect(delRes.status).toBe(204);

      // 5. Verify deleted
      const verifyRes = await request(app).get(`/api/v1/bookmarks/${bookmarkId}`);
      expect(verifyRes.status).toBe(404);
    });
  });
});

