import { describe, it, expect, beforeEach } from 'vitest';
import request from 'supertest';
import { app } from '../src/app.js';
import { bookmarkService } from '../src/services/bookmark-service.js';

interface BookmarkResponse {
  id: string;
  url: string;
  title?: string;
  tags?: string[];
  createdAt: string;
}

function isBookmarkResponse(val: unknown): val is BookmarkResponse {
  if (typeof val !== 'object' || val === null) {
    return false;
  }
  const rec = val as Record<string, unknown>;
  return (
    typeof rec['id'] === 'string' &&
    typeof rec['url'] === 'string' &&
    typeof rec['createdAt'] === 'string'
  );
}

function isBookmarkArray(val: unknown): val is BookmarkResponse[] {
  return Array.isArray(val) && val.every(isBookmarkResponse);
}

interface PaginatedBookmarkResponse {
  data: BookmarkResponse[];
  pagination: {
    page: number;
    limit: number;
    total: number;
    totalPages: number;
  };
}

function isPaginatedBookmarkResponse(val: unknown): val is PaginatedBookmarkResponse {
  if (typeof val !== 'object' || val === null) {
    return false;
  }
  const rec = val as Record<string, unknown>;
  if (!Array.isArray(rec['data']) || !rec['data'].every(isBookmarkResponse)) {
    return false;
  }
  if (typeof rec['pagination'] !== 'object' || rec['pagination'] === null) {
    return false;
  }
  const pag = rec['pagination'] as Record<string, unknown>;
  return (
    typeof pag['page'] === 'number' &&
    typeof pag['limit'] === 'number' &&
    typeof pag['total'] === 'number' &&
    typeof pag['totalPages'] === 'number'
  );
}

describe('Bookmarks API Integration Tests', () => {
  beforeEach(() => {
    bookmarkService.clear();
  });

  describe('POST /api/v1/bookmarks', () => {
    it('should successfully create a new bookmark and return 201', async () => {
      const payload = {
        url: 'https://vitest.dev',
        title: 'Vitest Testing Framework',
        tags: ['testing', 'vite'],
      };

      const res = await request(app)
        .post('/api/v1/bookmarks')
        .send(payload);

      expect(res.status).toBe(201);
      const body: unknown = res.body;
      expect(isBookmarkResponse(body)).toBe(true);

      if (isBookmarkResponse(body)) {
        expect(body.url).toBe(payload.url);
        expect(body.title).toBe(payload.title);
        expect(body.tags).toEqual(payload.tags);
        expect(typeof body.id).toBe('string');
        expect(typeof body.createdAt).toBe('string');
      }
    });
  });

  describe('GET /api/v1/bookmarks (list)', () => {
    it('should return 200 with paginated bookmarks sorted by createdAt descending', async () => {
      const first = await request(app)
        .post('/api/v1/bookmarks')
        .send({ url: 'https://first.com', title: 'First' });

      const second = await request(app)
        .post('/api/v1/bookmarks')
        .send({ url: 'https://second.com', title: 'Second' });

      const res = await request(app).get('/api/v1/bookmarks');

      expect(res.status).toBe(200);
      const body: unknown = res.body;
      expect(isPaginatedBookmarkResponse(body)).toBe(true);

      if (isPaginatedBookmarkResponse(body)) {
        expect(body.data).toHaveLength(2);
        expect(body.pagination).toEqual({
          page: 1,
          limit: 20,
          total: 2,
          totalPages: 1,
        });

        const firstBody: unknown = first.body;
        const secondBody: unknown = second.body;
        if (isBookmarkResponse(firstBody) && isBookmarkResponse(secondBody)) {
          expect(body.data[0]?.id).toBe(secondBody.id);
          expect(body.data[1]?.id).toBe(firstBody.id);
        }
      }
    });
  });

  describe('GET /api/v1/bookmarks/:id (single)', () => {
    it('should return 200 and the bookmark matching the given id', async () => {
      const createRes = await request(app)
        .post('/api/v1/bookmarks')
        .send({ url: 'https://single.com', title: 'Single' });

      const created: unknown = createRes.body;
      expect(isBookmarkResponse(created)).toBe(true);

      if (isBookmarkResponse(created)) {
        const res = await request(app).get(`/api/v1/bookmarks/${created.id}`);

        expect(res.status).toBe(200);
        const body: unknown = res.body;
        expect(isBookmarkResponse(body)).toBe(true);
        if (isBookmarkResponse(body)) {
          expect(body.id).toBe(created.id);
          expect(body.url).toBe(created.url);
          expect(body.title).toBe(created.title);
        }
      }
    });
  });

  describe('GET /api/v1/bookmarks pagination & edge cases', () => {
    it('should normalize page 0 to page 1', async () => {
      await request(app)
        .post('/api/v1/bookmarks')
        .send({ url: 'https://page-zero.com' });

      const res = await request(app).get('/api/v1/bookmarks?page=0');

      expect(res.status).toBe(200);
      const body: unknown = res.body;
      expect(isPaginatedBookmarkResponse(body)).toBe(true);
      if (isPaginatedBookmarkResponse(body)) {
        expect(body.pagination.page).toBe(1);
        expect(body.data).toHaveLength(1);
      }
    });

    it('should normalize negative limit to default limit (20)', async () => {
      await request(app)
        .post('/api/v1/bookmarks')
        .send({ url: 'https://negative-limit.com' });

      const res = await request(app).get('/api/v1/bookmarks?limit=-10');

      expect(res.status).toBe(200);
      const body: unknown = res.body;
      expect(isPaginatedBookmarkResponse(body)).toBe(true);
      if (isPaginatedBookmarkResponse(body)) {
        expect(body.pagination.limit).toBe(20);
      }
    });

    it('should cap limit > 100 at 100', async () => {
      const res = await request(app).get('/api/v1/bookmarks?limit=250');

      expect(res.status).toBe(200);
      const body: unknown = res.body;
      expect(isPaginatedBookmarkResponse(body)).toBe(true);
      if (isPaginatedBookmarkResponse(body)) {
        expect(body.pagination.limit).toBe(100);
      }
    });

    it('should correctly paginate across multiple pages', async () => {
      for (let i = 1; i <= 25; i++) {
        await request(app)
          .post('/api/v1/bookmarks')
          .send({ url: `https://item-${i}.com`, title: `Item ${i}` });
      }

      const page1Res = await request(app).get('/api/v1/bookmarks?page=1&limit=10');
      expect(page1Res.status).toBe(200);
      const page1Body: unknown = page1Res.body;
      expect(isPaginatedBookmarkResponse(page1Body)).toBe(true);
      if (isPaginatedBookmarkResponse(page1Body)) {
        expect(page1Body.data).toHaveLength(10);
        expect(page1Body.pagination).toEqual({
          page: 1,
          limit: 10,
          total: 25,
          totalPages: 3,
        });
      }

      const page3Res = await request(app).get('/api/v1/bookmarks?page=3&limit=10');
      expect(page3Res.status).toBe(200);
      const page3Body: unknown = page3Res.body;
      expect(isPaginatedBookmarkResponse(page3Body)).toBe(true);
      if (isPaginatedBookmarkResponse(page3Body)) {
        expect(page3Body.data).toHaveLength(5);
        expect(page3Body.pagination).toEqual({
          page: 3,
          limit: 10,
          total: 25,
          totalPages: 3,
        });
      }
    });
  });

  describe('DELETE /api/v1/bookmarks/:id', () => {
    it('should delete the bookmark, returning 204, and verify subsequent 404', async () => {
      const createRes = await request(app)
        .post('/api/v1/bookmarks')
        .send({ url: 'https://delete-me.com' });

      const created: unknown = createRes.body;
      expect(isBookmarkResponse(created)).toBe(true);

      if (isBookmarkResponse(created)) {
        const deleteRes = await request(app).delete(`/api/v1/bookmarks/${created.id}`);
        expect(deleteRes.status).toBe(204);

        const getRes = await request(app).get(`/api/v1/bookmarks/${created.id}`);
        expect(getRes.status).toBe(404);
      }
    });
  });

  describe('Full CRUD lifecycle', () => {
    it('should handle full sequence: POST -> GET list -> GET single -> DELETE -> GET single 404', async () => {
      // 1. Create
      const postRes = await request(app)
        .post('/api/v1/bookmarks')
        .send({ url: 'https://full-lifecycle.com', title: 'Lifecycle' });
      expect(postRes.status).toBe(201);
      const postBody: unknown = postRes.body;
      expect(isBookmarkResponse(postBody)).toBe(true);
      if (!isBookmarkResponse(postBody)) return;

      const bookmarkId = postBody.id;

      // 2. List
      const listRes = await request(app).get('/api/v1/bookmarks');
      expect(listRes.status).toBe(200);
      const listBody: unknown = listRes.body;
      expect(isPaginatedBookmarkResponse(listBody)).toBe(true);
      if (isPaginatedBookmarkResponse(listBody)) {
        expect(listBody.data.some((b) => b.id === bookmarkId)).toBe(true);
      }

      // 3. Single
      const singleRes = await request(app).get(`/api/v1/bookmarks/${bookmarkId}`);
      expect(singleRes.status).toBe(200);
      const singleBody: unknown = singleRes.body;
      expect(isBookmarkResponse(singleBody)).toBe(true);

      // 4. Delete
      const delRes = await request(app).delete(`/api/v1/bookmarks/${bookmarkId}`);
      expect(delRes.status).toBe(204);

      // 5. Verify deleted
      const verifyRes = await request(app).get(`/api/v1/bookmarks/${bookmarkId}`);
      expect(verifyRes.status).toBe(404);
    });
  });
});

