describe('PATCH /api/v1/bookmarks/:id', () => {
  it('should partially update title without altering url or tags', async () => {
    const createRes = await request(app)
      .post('/api/v1/bookmarks')
      .send({
        url: 'https://immutable-url.com',
        title: 'Original Title',
        tags: ['initial'],
      });

    const created: unknown = createRes.body;
    expect(isBookmarkResponse(created)).toBe(true);
    if (!isBookmarkResponse(created)) return;

    const patchRes = await request(app)
      .patch(`/api/v1/bookmarks/${created.id}`)
      .send({ title: 'Updated Title' });

    expect(patchRes.status).toBe(200);
    const patchBody: unknown = patchRes.body;
    expect(isBookmarkResponse(patchBody)).toBe(true);
    if (isBookmarkResponse(patchBody)) {
      expect(patchBody.id).toBe(created.id);
      expect(patchBody.url).toBe('https://immutable-url.com');
      expect(patchBody.title).toBe('Updated Title');
      expect(patchBody.tags).toEqual(['initial']);
    }
  });

  it('should partially update tags without altering title or url', async () => {
    const createRes = await request(app)
      .post('/api/v1/bookmarks')
      .send({
        url: 'https://tags-update.com',
        title: 'Preserved Title',
        tags: ['old-tag'],
      });

    const created: unknown = createRes.body;
    expect(isBookmarkResponse(created)).toBe(true);
    if (!isBookmarkResponse(created)) return;

    const patchRes = await request(app)
      .patch(`/api/v1/bookmarks/${created.id}`)
      .send({ tags: ['updated-tag', 'another-tag'] });

    expect(patchRes.status).toBe(200);
    const patchBody: unknown = patchRes.body;
    expect(isBookmarkResponse(patchBody)).toBe(true);
    if (isBookmarkResponse(patchBody)) {
      expect(patchBody.url).toBe('https://tags-update.com');
      expect(patchBody.title).toBe('Preserved Title');
      expect(patchBody.tags).toEqual(['updated-tag', 'another-tag']);
    }
  });

  it('should return 404 when attempting to patch a non-existent bookmark ID', async () => {
    const patchRes = await request(app)
      .patch('/api/v1/bookmarks/00000000-0000-0000-0000-000000000000')
      .send({ title: 'Ghost Title' });

    expect(patchRes.status).toBe(404);
    const body = patchRes.body as Record<string, unknown>;
    expect(body['error']).toBe('Bookmark not found');
  });

  it('should reject URL change attempt with 422 and keep original URL intact', async () => {
    const createRes = await request(app)
      .post('/api/v1/bookmarks')
      .send({ url: 'https://original-url.com', title: 'Steady' });

    const created: unknown = createRes.body;
    expect(isBookmarkResponse(created)).toBe(true);
    if (!isBookmarkResponse(created)) return;

    const patchRes = await request(app)
      .patch(`/api/v1/bookmarks/${created.id}`)
      .send({ url: 'https://tampered-url.com' });

    expect(patchRes.status).toBe(422);
    const errBody = patchRes.body as Record<string, unknown>;
    expect(errBody['error']).toBe('Validation failed');

    // Verify the original bookmark was not mutated
    const getRes = await request(app).get(`/api/v1/bookmarks/${created.id}`);
    expect(getRes.status).toBe(200);
    const getBody: unknown = getRes.body;
    expect(isBookmarkResponse(getBody)).toBe(true);
    if (isBookmarkResponse(getBody)) {
      expect(getBody.url).toBe('https://original-url.com');
    }
  });
});

