import { describe, it, expect, vi } from 'vitest';
import { EventEmitter } from 'node:events';
import { Request, Response } from 'express';
import { requestLogger, RequestLogEntry } from './logger.js';

function isRequestLogEntry(val: unknown): val is RequestLogEntry {
  if (typeof val !== 'object' || val === null) return false;
  const r = val as Record<string, unknown>;
  return (
    typeof r['method'] === 'string' &&
    typeof r['path'] === 'string' &&
    typeof r['status'] === 'number' &&
    typeof r['duration_ms'] === 'number'
  );
}

describe('requestLogger middleware', () => {
  it('should log method, path, status, and duration_ms as JSON on finish', () => {
    const consoleSpy = vi.spyOn(console, 'log').mockImplementation(() => {});

    const emitter = new EventEmitter();
    const req = {
      method: 'GET',
      originalUrl: '/api/v1/bookmarks?page=1',
      path: '/api/v1/bookmarks',
    } as unknown as Request;

    const res = Object.assign(emitter, {
      statusCode: 200,
    }) as unknown as Response;

    const next = vi.fn();

    requestLogger(req, res, next);
    expect(next).toHaveBeenCalledOnce();

    emitter.emit('finish');

    expect(consoleSpy).toHaveBeenCalledOnce();
    const loggedOutput: unknown = consoleSpy.mock.calls[0]?.[0];
    expect(typeof loggedOutput).toBe('string');

    if (typeof loggedOutput === 'string') {
      const parsed: unknown = JSON.parse(loggedOutput);
      expect(isRequestLogEntry(parsed)).toBe(true);
      if (isRequestLogEntry(parsed)) {
        expect(parsed.method).toBe('GET');
        expect(parsed.path).toBe('/api/v1/bookmarks');
        expect(parsed.status).toBe(200);
        expect(parsed.duration_ms).toBeGreaterThanOrEqual(0);
      }
    }

    consoleSpy.mockRestore();
  });
});

