import { randomUUID } from 'node:crypto';

export interface CreateBookmarkDTO {
  url: string;
  title?: string;
  tags?: string[];
}

export interface UpdateBookmarkDTO {
  title?: string;
  tags?: string[];
}

export interface Bookmark {
  id: string;
  url: string;
  title?: string;
  tags?: string[];
  createdAt: string;
}

export interface PaginatedResult<T> {
  data: T[];
  pagination: {
    page: number;
    limit: number;
    total: number;
    totalPages: number;
  };
}

export class DuplicateBookmarkError extends Error {
  constructor(url: string) {
    super(`Bookmark with URL already exists: ${url}`);
    this.name = 'DuplicateBookmarkError';
  }
}

export class BookmarkService {
  private readonly bookmarks: Map<string, Bookmark> = new Map();

  /**
   * Creates and stores a new bookmark.
   *
   * @param input - The payload containing the URL and optional title and tags.
   * @returns The newly created bookmark with generated ID and createdAt timestamp.
   * @throws {DuplicateBookmarkError} When a bookmark with the identical URL already exists.
   *
   * @example
   * ```ts
   * const bookmark = service.create({
   *   url: 'https://example.com',
   *   title: 'Example Domain',
   *   tags: ['web', 'standards']
   * });
   * ```
   */
  create(input: CreateBookmarkDTO): Bookmark {
    for (const bookmark of this.bookmarks.values()) {
      if (bookmark.url === input.url) {
        throw new DuplicateBookmarkError(input.url);
      }
    }

    const bookmark: Bookmark = {
      id: randomUUID(),
      url: input.url,
      ...(input.title !== undefined ? { title: input.title } : {}),
      ...(input.tags !== undefined ? { tags: [...input.tags] } : {}),
      createdAt: new Date().toISOString(),
    };

    this.bookmarks.set(bookmark.id, bookmark);
    return bookmark;
  }

  /**
   * Retrieves a bookmark by its unique identifier.
   *
   * @param id - The UUID of the bookmark to look up.
   * @returns The matching bookmark if found, otherwise undefined.
   *
   * @example
   * ```ts
   * const bookmark = service.getById('123e4567-e89b-12d3-a456-426614174000');
   * if (bookmark) {
   *   console.log(bookmark.title);
   * }
   * ```
   */
  getById(id: string): Bookmark | undefined {
    return this.bookmarks.get(id);
  }

  /**
   * Alias for `getById`. Retrieves a bookmark by its unique identifier.
   *
   * @param id - The UUID of the bookmark to look up.
   * @returns The matching bookmark if found, otherwise undefined.
   *
   * @example
   * ```ts
   * const bookmark = service.get('123e4567-e89b-12d3-a456-426614174000');
   * ```
   */
  get(id: string): Bookmark | undefined {
    return this.getById(id);
  }

  /**
   * Retrieves all stored bookmarks sorted by creation date descending.
   *
   * @returns An array containing all bookmarks in descending order of createdAt.
   *
   * @example
   * ```ts
   * const bookmarks = service.getAll();
   * console.log(`Total bookmarks: ${bookmarks.length}`);
   * ```
   */
  getAll(): Bookmark[] {
    const list = Array.from(this.bookmarks.values()).reverse();
    return list.sort((a, b) => {
      return new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime();
    });
  }

  /**
   * Retrieves a paginated subset of bookmarks sorted by creation date descending.
   *
   * @param page - 1-based page number.
   * @param limit - Maximum number of bookmarks per page.
   * @returns A PaginatedResult object containing the bookmark data slice and pagination metadata.
   *
   * @example
   * ```ts
   * const result = service.getPaginated(1, 20);
   * console.log(result.data, result.pagination.totalPages);
   * ```
   */
  getPaginated(page: number, limit: number): PaginatedResult<Bookmark> {
    const all = this.getAll();
    const total = all.length;
    const totalPages = Math.ceil(total / limit);
    const startIndex = (page - 1) * limit;
    const data = all.slice(startIndex, startIndex + limit);

    return {
      data,
      pagination: {
        page,
        limit,
        total,
        totalPages,
      },
    };
  }

  /**
   * Updates an existing bookmark with partial modifications. The URL cannot be altered.
   *
   * @param id - The UUID of the bookmark to update.
   * @param updates - Object containing optional new title and/or tags.
   * @returns The updated bookmark if found, otherwise undefined.
   *
   * @example
   * ```ts
   * const updated = service.update('123e4567-e89b-12d3-a456-426614174000', {
   *   title: 'Updated Title',
   *   tags: ['updated']
   * });
   * ```
   */
  update(id: string, updates: UpdateBookmarkDTO): Bookmark | undefined {
    const existing = this.bookmarks.get(id);
    if (!existing) {
      return undefined;
    }

    const updated: Bookmark = {
      ...existing,
      ...(updates.title !== undefined ? { title: updates.title } : {}),
      ...(updates.tags !== undefined ? { tags: [...updates.tags] } : {}),
    };

    this.bookmarks.set(id, updated);
    return updated;
  }

  /**
   * Searches bookmarks by title (case-insensitive substring) and tags (exact match).
   *
   * @param query - The search query term.
   * @returns An array of matching bookmarks sorted by createdAt descending.
   *
   * @example
   * ```ts
   * const results = service.search('typescript');
   * ```
   */
  search(query: string): Bookmark[] {
    const trimmed = query.trim().toLowerCase();
    if (!trimmed) {
      return [];
    }

    const all = this.getAll();
    return all.filter((bookmark) => {
      const titleMatches =
        bookmark.title !== undefined &&
        bookmark.title.toLowerCase().includes(trimmed);

      const tagMatches =
        bookmark.tags !== undefined &&
        bookmark.tags.some((tag) => tag.toLowerCase() === trimmed);

      return titleMatches || tagMatches;
    });
  }

  /**
   * Removes a bookmark by its unique identifier.
   *
   * @param id - The UUID of the bookmark to remove.
   * @returns True if the bookmark existed and was removed, false otherwise.
   *
   * @example
   * ```ts
   * const wasDeleted = service.delete('123e4567-e89b-12d3-a456-426614174000');
   * ```
   */
  delete(id: string): boolean {
    return this.bookmarks.delete(id);
  }

  /**
   * Clears all stored bookmarks from the in-memory store.
   *
   * @returns void
   *
   * @example
   * ```ts
   * service.clear();
   * ```
   */
  clear(): void {
    this.bookmarks.clear();
  }
}

export const bookmarkService = new BookmarkService();

import { Router, Request, Response, NextFunction } from 'express';
import { z } from 'zod';
import { bookmarkService } from '../services/bookmark-service.js';

export const createBookmarkSchema = z.object({
  url: z.string().url().max(2048),
  title: z.string().max(200).optional(),
  tags: z.array(z.string().max(50)).max(10).optional(),
});

export type CreateBookmarkInput = z.infer<typeof createBookmarkSchema>;

export const updateBookmarkSchema = z
  .object({
    title: z.string().max(200).optional(),
    tags: z.array(z.string().max(50)).max(10).optional(),
  })
  .passthrough()
  .refine((data) => !('url' in data), {
    message: 'URL is immutable and cannot be updated',
    path: ['url'],
  });

export type UpdateBookmarkInput = z.infer<typeof updateBookmarkSchema>;

/**
 * Route handler for GET /api/v1/bookmarks
 * Returns a paginated list of bookmarks sorted by creation date descending.
 *
 * @param req - Express Request with optional `page` and `limit` query parameters.
 * @param res - Express Response returning paginated bookmarks.
 * @returns void
 *
 * @example
 * // Client request: GET /api/v1/bookmarks?page=1&limit=20
 * // Responds with 200: { data: [...], pagination: { page: 1, limit: 20, total: 1, totalPages: 1 } }
 */
export function listBookmarksHandler(req: Request, res: Response): void {
  const pageQuery = req.query['page'];
  const limitQuery = req.query['limit'];

  const pageParsed = typeof pageQuery === 'string' ? parseInt(pageQuery, 10) : NaN;
  const limitParsed = typeof limitQuery === 'string' ? parseInt(limitQuery, 10) : NaN;

  const page = Number.isNaN(pageParsed) || pageParsed < 1 ? 1 : pageParsed;
  const limit =
    Number.isNaN(limitParsed) || limitParsed < 1
      ? 20
      : limitParsed > 100
        ? 100
        : limitParsed;

  const result = bookmarkService.getPaginated(page, limit);
  res.status(200).json(result);
}

/**
 * Route handler for GET /api/v1/bookmarks/search
 * Searches bookmarks by title (case-insensitive substring) and tags (exact match).
 *
 * @param req - Express Request with mandatory non-empty `q` query parameter.
 * @param res - Express Response returning array of matching bookmarks or 400 on error.
 * @returns void
 *
 * @example
 * // Client request: GET /api/v1/bookmarks/search?q=typescript
 * // Responds with 200: [{ id: '...', url: '...', title: 'TypeScript Docs', tags: ['typescript'] }]
 */
export function searchBookmarksHandler(req: Request, res: Response): void {
  const q = req.query['q'];
  if (typeof q !== 'string' || q.trim() === '') {
    res.status(400).json({ error: 'Search query "q" is required and cannot be empty' });
    return;
  }

  const results = bookmarkService.search(q);
  res.status(200).json(results);
}

/**
 * Route handler for GET /api/v1/bookmarks/:id
 * Retrieves a single bookmark by its ID.
 *
 * @param req - Express Request containing the bookmark `id` route parameter.
 * @param res - Express Response returning the bookmark or 404 if not found.
 * @returns void
 *
 * @example
 * // Client request: GET /api/v1/bookmarks/123e4567-e89b-12d3-a456-426614174000
 * // Responds with 200: { id: '...', url: 'https://example.com', title: 'Example' }
 */
export function getBookmarkByIdHandler(req: Request, res: Response): void {
  const id = req.params['id'];
  if (typeof id !== 'string') {
    res.status(400).json({ error: 'Invalid id parameter' });
    return;
  }

  const bookmark = bookmarkService.getById(id);
  if (!bookmark) {
    res.status(404).json({ error: 'Bookmark not found' });
    return;
  }

  res.status(200).json(bookmark);
}

/**
 * Route handler for DELETE /api/v1/bookmarks/:id
 * Deletes a single bookmark by its ID.
 *
 * @param req - Express Request containing the bookmark `id` route parameter.
 * @param res - Express Response returning 204 on success or 404 if not found.
 * @returns void
 *
 * @example
 * // Client request: DELETE /api/v1/bookmarks/123e4567-e89b-12d3-a456-426614174000
 * // Responds with 204 No Content
 */
export function deleteBookmarkHandler(req: Request, res: Response): void {
  const id = req.params['id'];
  if (typeof id !== 'string') {
    res.status(400).json({ error: 'Invalid id parameter' });
    return;
  }

  const deleted = bookmarkService.delete(id);
  if (!deleted) {
    res.status(404).json({ error: 'Bookmark not found' });
    return;
  }

  res.status(204).send();
}

/**
 * Route handler for PATCH /api/v1/bookmarks/:id
 * Partially updates a bookmark's title and/or tags. Rejects any attempt to modify url.
 *
 * @param req - Express Request containing bookmark `id` param and partial update body.
 * @param res - Express Response returning the updated bookmark or 404/422.
 * @param next - Express NextFunction to pass errors to error handling middleware.
 * @returns void
 *
 * @example
 * // Client request: PATCH /api/v1/bookmarks/123e4567-e89b-12d3-a456-426614174000
 * // Body: { title: 'Updated Title' }
 * // Responds with 200: { id: '...', url: '...', title: 'Updated Title' }
 */
export function updateBookmarkHandler(
  req: Request,
  res: Response,
  next: NextFunction
): void {
  try {
    const id = req.params['id'];
    if (typeof id !== 'string') {
      res.status(400).json({ error: 'Invalid id parameter' });
      return;
    }

    const body: unknown = req.body;
    const validatedData = updateBookmarkSchema.parse(body);

    const updated = bookmarkService.update(id, validatedData);
    if (!updated) {
      res.status(404).json({ error: 'Bookmark not found' });
      return;
    }

    res.status(200).json(updated);
  } catch (err: unknown) {
    next(err);
  }
}

/**
 * Route handler for POST /api/v1/bookmarks
 * Creates a new bookmark after validating the payload against createBookmarkSchema.
 *
 * @param req - Express Request containing bookmark JSON payload { url, title?, tags? }.
 * @param res - Express Response returning 201 Created with the new bookmark.
 * @param next - Express NextFunction to pass errors to error handling middleware.
 * @returns void
 *
 * @example
 * // Client request: POST /api/v1/bookmarks
 * // Body: { url: 'https://example.com', title: 'Example', tags: ['reference'] }
 * // Responds with 201: { id: '...', url: 'https://example.com', createdAt: '...' }
 */
export function createBookmarkHandler(
  req: Request,
  res: Response,
  next: NextFunction
): void {
  try {
    const body: unknown = req.body;
    const validatedData = createBookmarkSchema.parse(body);
    const bookmark = bookmarkService.create(validatedData);
    res.status(201).json(bookmark);
  } catch (err: unknown) {
    next(err);
  }
}

export const bookmarksRouter = Router();

bookmarksRouter.get('/', listBookmarksHandler);
bookmarksRouter.get('/search', searchBookmarksHandler);
bookmarksRouter.get('/:id', getBookmarkByIdHandler);
bookmarksRouter.delete('/:id', deleteBookmarkHandler);
bookmarksRouter.patch('/:id', updateBookmarkHandler);
bookmarksRouter.post('/', createBookmarkHandler);

export default bookmarksRouter;

